import{_ as a,c as e,o as d,a2 as r}from"./chunks/framework.BKNXJ1nb.js";const n=JSON.parse('{"title":"事件积木","description":"","frontmatter":{},"headers":[],"relativePath":"scratch-book-preview/4.事件积木.md","filePath":"scratch-book-preview/4.事件积木.md"}'),o={name:"scratch-book-preview/4.事件积木.md"};function h(l,t,c,s,b,i){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="事件积木" tabindex="-1">事件积木 <a class="header-anchor" href="#事件积木" aria-label="Permalink to &quot;事件积木&quot;">​</a></h1><p>事件积木是黄色的，一共 9 块。它们是脚本的发令枪——每块都是一顶帽子，帽子下面挂的脚本会在对应事情发生时开始跑：点绿旗、按按键、点角色、收到广播。一个角色可以挂好几顶帽子，各跑各的，互不干扰。</p><h2 id="_1-当-greenflag-被点击" tabindex="-1">1. 当 @greenFlag 被点击 <a class="header-anchor" href="#_1-当-greenflag-被点击" aria-label="Permalink to &quot;1. 当 @greenFlag 被点击&quot;">​</a></h2><pre class="blocks"><code>当 @greenFlag 被点击</code></pre><p>点绿旗，帽子下面的脚本开始跑；再点一次，又从头跑一遍。</p><p>没有参数。</p><h2 id="_2-当按下-空格-v-键" tabindex="-1">2. 当按下 [空格 v] 键 <a class="header-anchor" href="#_2-当按下-空格-v-键" aria-label="Permalink to &quot;2. 当按下 [空格 v] 键&quot;">​</a></h2><pre class="blocks"><code>当按下 [空格 v] 键</code></pre><p>按下这个键，脚本开始跑。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>按键</td><td>下拉选要听的键，还支持&quot;任意&quot;</td><td>无</td></tr></tbody></table><h2 id="_3-当角色被点击" tabindex="-1">3. 当角色被点击 <a class="header-anchor" href="#_3-当角色被点击" aria-label="Permalink to &quot;3. 当角色被点击&quot;">​</a></h2><pre class="blocks"><code>当角色被点击</code></pre><p>鼠标点到这个角色，脚本开始跑。</p><p>没有参数。</p><h2 id="_4-当舞台被点击" tabindex="-1">4. 当舞台被点击 <a class="header-anchor" href="#_4-当舞台被点击" aria-label="Permalink to &quot;4. 当舞台被点击&quot;">​</a></h2><pre class="blocks"><code>当舞台被点击</code></pre><p>鼠标点到舞台空白处，脚本开始跑。</p><p>没有参数。</p><h2 id="_5-当背景换成-下一个背景-v" tabindex="-1">5. 当背景换成 [下一个背景 v] <a class="header-anchor" href="#_5-当背景换成-下一个背景-v" aria-label="Permalink to &quot;5. 当背景换成 [下一个背景 v]&quot;">​</a></h2><pre class="blocks"><code>当背景换成 [下一个背景 v]</code></pre><p>舞台背景一换成它，脚本开始跑。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>背景</td><td>下拉选某个背景或&quot;下一个背景&quot;</td><td>无</td></tr></tbody></table><h2 id="_6-当接收到-消息1-v" tabindex="-1">6. 当接收到 [消息1 v] <a class="header-anchor" href="#_6-当接收到-消息1-v" aria-label="Permalink to &quot;6. 当接收到 [消息1 v]&quot;">​</a></h2><pre class="blocks"><code>当接收到 [消息1 v]</code></pre><p>别的积木广播了这条消息，脚本开始跑。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>消息</td><td>下拉选消息名，可以现场新建</td><td>无</td></tr></tbody></table><h2 id="_7-广播-消息1-v" tabindex="-1">7. 广播 [消息1 v] <a class="header-anchor" href="#_7-广播-消息1-v" aria-label="Permalink to &quot;7. 广播 [消息1 v]&quot;">​</a></h2><pre class="blocks"><code>广播 [消息1 v]</code></pre><p>发出一条消息，所有在听的脚本同时起跑；自己的脚本不等，继续往下走。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>消息</td><td>下拉选消息名</td><td>无</td></tr></tbody></table><h2 id="_8-广播-消息1-v-并等待" tabindex="-1">8. 广播 [消息1 v] 并等待 <a class="header-anchor" href="#_8-广播-消息1-v-并等待" aria-label="Permalink to &quot;8. 广播 [消息1 v] 并等待&quot;">​</a></h2><pre class="blocks"><code>广播 [消息1 v] 并等待</code></pre><p>发出消息后停在这里，等收到的脚本全部跑完，自己才继续。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>消息</td><td>下拉选消息名</td><td>无</td></tr></tbody></table><h2 id="_9-当-响度-v-10" tabindex="-1">9. 当 [响度 v] &gt; (10) <a class="header-anchor" href="#_9-当-响度-v-10" aria-label="Permalink to &quot;9. 当 [响度 v] &gt; (10)&quot;">​</a></h2><pre class="blocks"><code>当 [响度 v] &gt; (10)</code></pre><p>麦克风响度（或计时器）超过数值时，脚本开始跑。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>项目</td><td>下拉选&quot;响度&quot;或&quot;计时器&quot;</td><td>无</td></tr><tr><td>阈值</td><td>超过它就触发；响度 0 ~ 100，计时器按秒数</td><td>—</td></tr></tbody></table>',38)])])}const _=a(o,[["render",h]]);export{n as __pageData,_ as default};
